"use client";

import { useEffect, useState } from "react";

interface Post {
    id: string;
    title: string;
    excerpt: string;
    createdAt: string;
    type: string;
    author: {
        name: string;
    }
}
const demoPosts: Post[] = [
    { id: "1", title: "Олон улсын зуслангийн эрдэмтэн судлаачдын хурал болно", excerpt: "Ази номхон далайн орнуудын болон бусад олон улсын судлаачид оролцох уг хурлын бүртгэл эхэллээ.", createdAt: "2024-03-01T00:00:00Z", type: "NEWS", author: { name: "Админ" } },
    { id: "2", title: "Артектай хамтран ажиллах санамж бичиг зурлаа", excerpt: "Монголын хүүхэд багачуудыг ОХУ-ын Хар тэнгисийн эрэгт байрлах дэлхийд танигдсан Артек зусланд амраах хөтөлбөрийг албан ёсоор эхлүүллээ.", createdAt: "2024-03-05T00:00:00Z", type: "NEWS", author: { name: "Админ" } },
    { id: "3", title: "Зуслангийн удирдлага, багш нарын сургалт", excerpt: "Зуны амралт эхлэхээс өмнө зуслангийн багш, ажилчдад зориулсан 3 өдрийн сургалтыг зохион байгууллаа.", createdAt: "2024-03-10T00:00:00Z", type: "NEWS", author: { name: "С.Батбилэг" } },
];

export default function NewsPage() {
    const [posts, setPosts] = useState<Post[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        async function fetchPosts() {
            try {
                const response = await fetch("/api/posts?type=NEWS");
                const data = await response.json();
                if (Array.isArray(data)) {
                    setPosts(data.length > 0 ? data : demoPosts);
                }
            } catch (error) {
                console.error("Failed to load news", error);
            } finally {
                setLoading(false);
            }
        }

        fetchPosts();
    }, []);

    const formatDate = (dateString: string) => {
        return new Date(dateString).toLocaleDateString('mn-MN');
    };

    return (
        <div className="container mx-auto px-4 py-12 md:py-24">
            <div className="space-y-4 text-center mb-12">
                <h1 className="text-4xl font-bold tracking-tighter sm:text-5xl text-primary">Мэдээ, Мэдээлэл</h1>
                <p className="text-lg text-muted-foreground">
                    Цаг үеийн болон байгууллагын онцлох мэдээ.
                </p>
            </div>

            {loading ? (
                <div className="flex justify-center py-20">
                    <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
                </div>
            ) : posts.length > 0 ? (
                <div className="grid gap-8 md:grid-cols-2 lg:grid-cols-3">
                    {posts.map((post) => (
                        <article key={post.id} className="group flex flex-col space-y-2">
                            <div className="aspect-video w-full rounded-lg bg-muted object-cover transition-colors hover:bg-muted/80" />
                            <div className="space-y-1">
                                <h3 className="text-2xl font-bold leading-tight group-hover:text-primary transition-colors">
                                    {post.title}
                                </h3>
                                <p className="text-muted-foreground line-clamp-3">
                                    {post.excerpt || "Дэлгэрэнгүйг дарж орж үзнэ үү."}
                                </p>
                            </div>
                            <div className="flex items-center space-x-2 text-sm text-muted-foreground">
                                <div className="font-semibold">{post.author?.name || "Админ"}</div>
                                <div>•</div>
                                <div>{formatDate(post.createdAt)}</div>
                            </div>
                        </article>
                    ))}
                </div>
            ) : (
                <div className="text-center py-20 border rounded-lg bg-slate-50">
                    <h3 className="text-lg font-medium text-slate-600">Одоогоор мэдээ оруулаагүй байна.</h3>
                </div>
            )}
        </div>
    );
}
